const wc = $('When Called').first().json;
const key = ((($('Get Anthropic Key').first() || {}).json || {}).key || '').toString().trim();
const ra = (($('Resolve Agent').first() || {}).json) || {};
const up = $json || {};
let fileMap = Array.isArray(up.file_map) ? up.file_map.slice() : [];
fileMap.sort(function(a,b){ return (Number(a.order||0)) - (Number(b.order||0)); });
const content = [];
for (const f of fileMap) { if (f && f.file_id) content.push({ type: 'image', source: { type: 'file', file_id: f.file_id } }); }
content.push({ type: 'text', text: String(wc.user_message || '') });
const warnings = Array.isArray(up.warnings) ? up.warnings.slice() : [];
// ADR-054 Block 2: per-user ClickUp scope binding (the enforcement point). Resolve Agent returned this
// caller's per-user Anthropic Vault id (holding their MCP-OAuth ClickUp credential) or null if they have
// no active credential. The vault is set by n8n from caller_user_id only -> unspoofable by the agent.
// When absent: degrade (no scoped ClickUp tools attached) + one consolidated WARN -> onboard that user.
const clickup_mcp_vault_id = (ra.clickup_mcp_vault_id || '').toString().trim();
const clickup_scope = clickup_mcp_vault_id ? 'scoped' : 'degraded';
if (!clickup_mcp_vault_id) {
  warnings.push({ source: 'managed-agents/clickup-scope-degraded', err: 'Uzytkownik ' + (wc.caller_user_id || '?') + ' nie ma aktywnego poswiadczenia ClickUp (OAuth) - sesja bez zakresowanego dostepu do ClickUp (discovery); zonbarduj tego uzytkownika przez clickup-oauth-start', severity: 'WARN' });
}
const message_body_json = JSON.stringify({ events: [{ type: 'user.message', content: content }] });
return [{ json: {
  key: key,
  agent_id: ra.agent_id || '',
  model_id: ra.model_id || '',
  environment_id: ra.environment_id || '',
  image_mcp_vault_id: ra.image_mcp_vault_id || '',
  clickup_mcp_vault_id: clickup_mcp_vault_id,
  clickup_scope: clickup_scope,
  file_map_json: JSON.stringify(fileMap),
  warnings_json: JSON.stringify(warnings),
  message_body_json: message_body_json,
  impact: wc.impact || '__default__',
  clickup_task_id: wc.clickup_task_id || '',
  caller_user_id: wc.caller_user_id || '',
  process_type: wc.process_type || '',
  triggered_by: wc.triggered_by || 'explicit_mention',
  invocation_type: wc.invocation_type || 'explicit'
} }];

const bs = $('Build Setup').first().json;
const sess = ($('Create Session').first() || {}).json || {};
const SOFT_DEADLINE_MS = 840000;
return [{ json: {
  session_id: sess.id || '',
  anthropic_key: bs.key,
  file_map_json: bs.file_map_json,
  deadline_epoch: Date.now() + SOFT_DEADLINE_MS,
  tool_round: 0,
  images_json: '[]',
  warnings_json: bs.warnings_json,
  agent_id: bs.agent_id,
  model_id: bs.model_id,
  impact: bs.impact,
  clickup_task_id: bs.clickup_task_id,
  caller_user_id: bs.caller_user_id,
  process_type: bs.process_type,
  triggered_by: bs.triggered_by,
  invocation_type: bs.invocation_type, clickup_scope: bs.clickup_scope
} }];

const wc = $('When Called').first().json;
const e = $json || {};
const err = (e.error && (e.error.message || e.error)) || e.message || JSON.stringify(e).slice(0,300);
return [{ json: {
  status: 'failed', output_message: '', files: [], file_ids: [], usd_cost: null, usd_cost_stub: true,
  session_usage: {}, duration_seconds: null, web_search_count: 0, model_used: '', agent_id: '', session_id: '',
  impact: wc.impact || '', clickup_task_id: wc.clickup_task_id || '',
  warnings: [{ source: 'managed-agents/session-create-failed', err: String(err).slice(0,400), severity: 'CRITICAL' }],
  failure_kind: 'create', outcome: 'create_failed'
} }];

const wc = $('When Called').first().json;
const sess = ($('Create Session').first() || {}).json || {};
const e = $json || {};
const err = (e.error && (e.error.message || e.error)) || e.message || JSON.stringify(e).slice(0,300);
return [{ json: {
  status: 'failed', output_message: '', files: [], file_ids: [], usd_cost: null, usd_cost_stub: true,
  session_usage: {}, duration_seconds: null, web_search_count: 0, model_used: '', agent_id: '', session_id: sess.id || '',
  impact: wc.impact || '', clickup_task_id: wc.clickup_task_id || '',
  warnings: [{ source: 'managed-agents/session-send-failed', err: String(err).slice(0,400), severity: 'CRITICAL' }],
  failure_kind: 'send', outcome: 'send_failed'
} }];

const st = $json;
const KEY = st.anthropic_key;
const SESSION = st.session_id;
const deadlineEpoch = Number(st.deadline_epoch) || (Date.now() + 840000);
const toolRound = Number(st.tool_round || 0);
const MAX_TOOL_ROUNDS = 12;
const POLL_INTERVAL_MS = 3000;
const MAX_CONSEC_ERRORS = 5;
const BASE = 'https://api.anthropic.com';
const BOTH = 'managed-agents-2026-04-01,files-api-2025-04-14';
const httpRequest = this.helpers.httpRequest;
const headers = { 'x-api-key': KEY, 'anthropic-version': '2023-06-01', 'anthropic-beta': BOTH };
const sleep = function(ms){ return new Promise(function(r){ setTimeout(r, ms); }); };
const remaining = function(){ return deadlineEpoch - Date.now(); };
async function getEvents(){
  const res = await httpRequest({ method: 'GET', url: BASE + '/v1/sessions/' + SESSION + '/events', headers: headers, json: true, returnFullResponse: true, timeout: 20000 });
  const body = res.body || {};
  return Array.isArray(body.data) ? body.data : [];
}
async function getStatus(){
  const res = await httpRequest({ method: 'GET', url: BASE + '/v1/sessions/' + SESSION, headers: headers, json: true, returnFullResponse: true, timeout: 20000 });
  return res.body || {};
}
function analyze(events){
  let lastUserIdx = -1;
  for (let i = 0; i < events.length; i++){ const t = events[i].type; if (t === 'user.message' || t === 'user.custom_tool_result') lastUserIdx = i; }
  const answered = {};
  for (const e of events){ if (e.type === 'user.custom_tool_result' && e.custom_tool_use_id) answered[e.custom_tool_use_id] = true; }
  const pending = [];
  for (const e of events){ if (e.type === 'agent.custom_tool_use' && !answered[e.id]) pending.push(e); }
  let agentRepliedAfter = false, lastAgentMsg = null;
  for (let i = 0; i < events.length; i++){ if (events[i].type === 'agent.message'){ lastAgentMsg = events[i]; if (i > lastUserIdx) agentRepliedAfter = true; } }
  let sessionError = null;
  let clickupAuthError = null;
  for (const e of events){ const t = e.type || ''; if (t === 'session.error' || (t.indexOf('error') >= 0 && e.error)){ const err = e.error || e; if (err && err.type === 'mcp_authentication_failed_error' && err.mcp_server_name === 'clickup'){ clickupAuthError = err; } else { sessionError = err; } } }
  let webSearchCount = 0;
  for (const e of events){ if (e.type === 'agent.tool_use' && e.name === 'web_search') webSearchCount++; }
  return { pending: pending, agentRepliedAfter: agentRepliedAfter, lastAgentMsg: lastAgentMsg, sessionError: sessionError, clickupAuthError: clickupAuthError, webSearchCount: webSearchCount };
}
function extractText(msg){ if (!msg) return ''; const c = msg.content || []; return c.filter(function(b){ return b && b.type === 'text'; }).map(function(b){ return b.text || ''; }).join(''); }
let outcome = null, picked = null, analysis = null, statusObj = {}, consecErr = 0;
await sleep(1500);
while (true){
  if (remaining() <= 0){ outcome = 'deadline'; break; }
  try {
    const events = await getEvents();
    statusObj = await getStatus();
    consecErr = 0;
    analysis = analyze(events);
    const status = statusObj.status;
    if (analysis.sessionError){ outcome = 'terminated'; break; }
    if (status === 'terminated'){ outcome = 'terminated'; break; }
    if (status === 'idle'){
      if (analysis.pending.length > 0){ if (toolRound >= MAX_TOOL_ROUNDS){ outcome = 'max_rounds'; } else { outcome = 'pending_tool'; picked = analysis.pending[0]; } break; }
      if (analysis.agentRepliedAfter){ outcome = 'done'; break; }
    }
  } catch (e){
    consecErr++;
    if (consecErr >= MAX_CONSEC_ERRORS){ outcome = 'poll_error'; break; }
  }
  if (remaining() <= 0){ outcome = 'deadline'; break; }
  await sleep(POLL_INTERVAL_MS);
}
const finalText = extractText(analysis ? analysis.lastAgentMsg : null);
return [{ json: Object.assign({}, st, {
  outcome: outcome,
  pending_tool_id: picked ? picked.id : '',
  pending_tool_name: picked ? picked.name : '',
  pending_tool_input_json: picked ? JSON.stringify(picked.input || {}) : '',
  final_message_text: finalText,
  web_search_count: analysis ? analysis.webSearchCount : 0,
  duration_seconds: (statusObj && statusObj.stats) ? statusObj.stats.duration_seconds : null,
  session_usage_json: JSON.stringify((statusObj && statusObj.usage) ? statusObj.usage : {}),
  terminated_error_json: (analysis && analysis.sessionError) ? JSON.stringify(analysis.sessionError).slice(0,500) : '',
  clickup_auth_error_json: (analysis && analysis.clickupAuthError) ? JSON.stringify(analysis.clickupAuthError).slice(0,500) : '',
  clickup_scope: st.clickup_scope || ''
}) }];

const h = $json || {};
const status = h.status || 'failed';
const file_ids = Array.isArray(h.file_ids) ? h.file_ids : [];
const msg = h.message || 'Image tool returned no message.';
const text = JSON.stringify({ status: status, file_ids: file_ids, message: msg, count_uploaded: h.count_uploaded, count_failed: h.count_failed });
return [{ json: {
  tool_result_text: text,
  new_images_json: JSON.stringify(Array.isArray(h.images) ? h.images : []),
  new_warnings_json: JSON.stringify(Array.isArray(h.warnings) ? h.warnings : [])
} }];

const st = $('Poll Round').first().json;
const name = st.pending_tool_name || 'unknown';
const text = JSON.stringify({ status: 'failed', message: 'The tool "' + name + '" is not available. Proceed without it and inform the user if relevant.' });
return [{ json: {
  tool_result_text: text,
  new_images_json: '[]',
  new_warnings_json: JSON.stringify([{ source: 'managed-agents/unknown-tool', err: 'agent requested an unregistered custom tool: ' + name, severity: 'WARN' }])
} }];

const h = $json || {};
let content = h.tool_result_content_json;
let warns = h.new_warnings_json;
if (!content) {
  content = JSON.stringify([{ type: 'text', text: 'Ekstrakcja zalacznika nie powiodla sie (blad narzedzia). Pracuj na podstawie dostepnego kontekstu i nie zglaszaj tego jako bledu.' }]);
  warns = JSON.stringify([{ source: 'managed-agents/extract-handler-failed', err: String((h.error && (h.error.message || h.error)) || 'brak wyniku ekstrakcji').slice(0, 300), severity: 'WARN' }]);
}
return [{ json: {
  tool_result_content_json: content,
  new_images_json: h.new_images_json || '[]',
  new_warnings_json: warns || '[]'
} }];

const h = $json || {};
let content = h.tool_result_content_json;
let warns = h.new_warnings_json;
if (!content) {
  content = JSON.stringify([{ type: 'text', text: 'Pobranie kontekstu zadania nie powiodlo sie (blad narzedzia). Pracuj na podstawie dostepnego kontekstu i nie zglaszaj tego jako bledu.' }]);
  warns = JSON.stringify([{ source: 'managed-agents/tail-handler-failed', err: String((h.error && (h.error.message || h.error)) || 'brak wyniku narzedzia tail').slice(0, 300), severity: 'WARN' }]);
}
return [{ json: {
  tool_result_content_json: content,
  new_images_json: h.new_images_json || '[]',
  new_warnings_json: warns || '[]'
} }];

const st = $('Poll Round').first().json;
const r = ($('Merge Result').first() || {}).json || {};
let images = []; try { images = JSON.parse(st.images_json || '[]'); } catch (e) {}
let warnings = []; try { warnings = JSON.parse(st.warnings_json || '[]'); } catch (e) {}
let ni = []; try { ni = JSON.parse(r.new_images_json || '[]'); } catch (e) {}
let nw = []; try { nw = JSON.parse(r.new_warnings_json || '[]'); } catch (e) {}
images = images.concat(ni);
warnings = warnings.concat(nw);
return [{ json: {
  session_id: st.session_id, anthropic_key: st.anthropic_key, file_map_json: st.file_map_json,
  deadline_epoch: st.deadline_epoch, tool_round: Number(st.tool_round || 0) + 1,
  images_json: JSON.stringify(images), warnings_json: JSON.stringify(warnings),
  agent_id: st.agent_id, model_id: st.model_id, impact: st.impact,
  clickup_task_id: st.clickup_task_id, caller_user_id: st.caller_user_id, process_type: st.process_type,
  triggered_by: st.triggered_by, invocation_type: st.invocation_type, clickup_scope: st.clickup_scope,
  user_message: '', input_images_json: ''
} }];

const st = $json;
let warnings = []; try { warnings = JSON.parse(st.warnings_json || '[]'); } catch (e) {}
let images = []; try { images = JSON.parse(st.images_json || '[]'); } catch (e) {}
let usage = {}; try { usage = JSON.parse(st.session_usage_json || '{}'); } catch (e) {}
const outcome = st.outcome;
let status = 'completed';
if (outcome === 'deadline'){ status = 'partial'; warnings.push({ source: 'managed-agents/session-deadline', err: 'Sesja agenta przekroczyla limit czasu (840s) - zwrocono wynik czesciowy', severity: 'WARN' }); }
else if (outcome === 'terminated'){ status = 'failed'; warnings.push({ source: 'managed-agents/session-error', err: 'Sesja zakonczona bledem: ' + (st.terminated_error_json || 'nieznany'), severity: 'WARN' }); }
else if (outcome === 'max_rounds'){ status = 'partial'; warnings.push({ source: 'managed-agents/max-tool-rounds', err: 'Osiagnieto limit rund narzedzia generate_image (12) - zwrocono wynik czesciowy', severity: 'WARN' }); }
else if (outcome === 'poll_error'){ status = 'partial'; warnings.push({ source: 'managed-agents/poll-error', err: 'Wielokrotne bledy odczytu zdarzen sesji - zwrocono wynik czesciowy', severity: 'WARN' }); }
// ADR-054 Block 3: a clickup MCP auth failure is NON-fatal (the run degrades, does not terminate). WARN only when the user IS onboarded (clickup_scope==='scoped') -> their scoped discovery silently broke (token/MCP). For un-onboarded ('degraded') it is expected and Build Setup already fired one consolidated WARN -> suppress the duplicate (operator decision 2026-06-23).
if (st.clickup_auth_error_json && st.clickup_scope === 'scoped'){ warnings.push({ source: 'managed-agents/clickup-scope-failed', err: 'Zakresowany dostep ClickUp (discovery) zawiodl mimo aktywnego poswiadczenia uzytkownika ' + (st.caller_user_id || '?') + ' - sprawdz token/MCP (mcp.clickup.com); szczegoly: ' + String(st.clickup_auth_error_json).slice(0,200), severity: 'WARN' }); }
const file_ids = images.map(function(im){ return im.file_id; }).filter(Boolean);

// --- Block 7: enumerate session OUTPUT office-docs (xlsx/docx/pptx/pdf produced by Skills/code-exec).
// Unlike images (purpose=agent, NOT downloadable), skill/code-exec OUTPUT files ARE downloadable from
// the Files API (Block 0). This listing is the AUTHORITATIVE, agent-independent source of produced doc
// file_ids (we do not rely on the agent emitting a file_id it may not reliably know). Post Reply (v1)
// downloads + validates + uploads them as ClickUp attachments. Fail-soft: a listing failure -> WARN +
// empty doc_files (the task still delivers its text/images). ~2.5s settle for the post-idle index lag.
let doc_files = [];
const DOC_MIMES = {
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
  'application/pdf': 'pdf'
};
if ((status === 'completed' || status === 'partial') && st.session_id && st.anthropic_key) {
  try {
    await new Promise(function(r){ setTimeout(r, 2500); });
    const dres = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.anthropic.com/v1/files?scope_id=' + encodeURIComponent(st.session_id), headers: { 'x-api-key': st.anthropic_key, 'anthropic-version': '2023-06-01', 'anthropic-beta': 'managed-agents-2026-04-01,files-api-2025-04-14' }, json: true, returnFullResponse: true, timeout: 30000 });
    const ddata = (dres.body && Array.isArray(dres.body.data)) ? dres.body.data : [];
    for (const f of ddata) {
      const mime = f.mime_type || '';
      const ext = DOC_MIMES[mime];
      if (f.downloadable === true && ext) doc_files.push({ file_id: f.id, filename: f.filename || (String(f.id) + '.' + ext), mime: mime, size_bytes: f.size_bytes || 0 });
    }
  } catch (e) {
    warnings.push({ source: 'managed-agents/doc-list-failed', err: 'Nie udalo sie wylistowac plikow wyjsciowych sesji (dokumenty moga nie zostac dostarczone): ' + String((e && e.message) || e).slice(0,200), severity: 'WARN' });
  }
}

// --- Block 6: session USD cost = token tiers + runtime + web search. Image cost is logged separately by Generate Images Parallel (no double-count). ---
// Per-1M-token USD (claude-api skill, 2026-06). Cache on input price: 5m write x1.25, 1h write x2.0, read x0.1.
const PRICES = {
  'claude-haiku-4-5':  { in: 1.00,  out: 5.00 },
  'claude-sonnet-4-6': { in: 3.00,  out: 15.00 },
  'claude-opus-4-8':   { in: 5.00,  out: 25.00 },
  'claude-fable-5':    { in: 10.00, out: 50.00 }
};
const RUNTIME_USD_PER_HOUR = 0.08;
const WEB_SEARCH_USD_PER_CALL = 0.01; // $10 / 1000
const model = st.model_id || '';
const cc = usage.cache_creation || {};
const tIn = Number(usage.input_tokens || 0);
const tOut = Number(usage.output_tokens || 0);
const tWrite5m = Number(cc.ephemeral_5m_input_tokens || 0);
const tWrite1h = Number(cc.ephemeral_1h_input_tokens || 0);
const tRead = Number(usage.cache_read_input_tokens || 0);
const dur = Number(st.duration_seconds || 0);
const ws = Number(st.web_search_count || 0);
const p = PRICES[model];
if (!p) { warnings.push({ source: 'managed-agents/cost-model-unknown', err: 'Brak cennika dla modelu ' + (model || '?') + ' - koszt sesji oszacowano cennikiem Opus 4.8 (gorny prog)', severity: 'WARN' }); }
const pr = p || PRICES['claude-opus-4-8'];
const tokenCost = (tIn/1e6)*pr.in + (tOut/1e6)*pr.out + (tWrite5m/1e6)*pr.in*1.25 + (tWrite1h/1e6)*pr.in*2.0 + (tRead/1e6)*pr.in*0.1;
const runtimeCost = RUNTIME_USD_PER_HOUR * (dur/3600);
const webSearchCost = ws * WEB_SEARCH_USD_PER_CALL;
const usd_cost = Number((tokenCost + runtimeCost + webSearchCost).toFixed(6));
if ((status === 'completed' || status === 'partial') && tIn === 0 && tOut === 0 && tRead === 0 && tWrite5m === 0 && tWrite1h === 0) {
  warnings.push({ source: 'managed-agents/cost-usage-missing', err: 'Sesja bez danych uzycia tokenow - koszt sesji moze byc zanizony', severity: 'WARN' });
}
// agent_runs.impact CHECK accepts: Niski / Sredni / Wysoki / Krytycznie wazne / 'n/d - zadanie nie jest dla AI'. Map anything else (e.g. __default__) to null.
const ALLOWED = ['Niski','Średni','Wysoki','Krytycznie ważne','n/d - zadanie nie jest dla AI'];
const cost_impact = (ALLOWED.indexOf(st.impact) >= 0) ? st.impact : null;

return [{ json: {
  status: status,
  output_message: st.final_message_text || '',
  files: images,
  file_ids: file_ids,
  doc_files: doc_files,
  usd_cost: usd_cost,
  usd_cost_stub: false,
  session_usage: usage,
  duration_seconds: (st.duration_seconds != null) ? st.duration_seconds : null,
  web_search_count: st.web_search_count || 0,
  model_used: st.model_id || '',
  agent_id: st.agent_id || '',
  session_id: st.session_id || '',
  impact: st.impact || '',
  cost_impact: cost_impact,
  clickup_task_id: st.clickup_task_id || '',
  triggered_by: st.triggered_by || 'explicit_mention',
  invocation_type: st.invocation_type || 'explicit',
  caller_user_id: st.caller_user_id || '',
  process_type: st.process_type || '',
  input_tokens: tIn,
  output_tokens: tOut,
  warnings: warnings,
  failure_kind: '',
  outcome: outcome
} }];

const o = $json;
let do_alert = false, sev = 'WARN', msg = '', det = '';
const warnings = Array.isArray(o.warnings) ? o.warnings : [];
if (o.failure_kind){ do_alert = true; sev = 'CRITICAL'; msg = 'Sesja Managed Agents nie wystartowala (' + o.failure_kind + ') dla zadania ' + (o.clickup_task_id || '?'); det = warnings.map(function(w){ return (w.source || '') + ': ' + (w.err || ''); }).join(' | ').slice(0,1500); }
else if (warnings.length > 0){ do_alert = true; const hasCrit = warnings.some(function(w){ return w.severity === 'CRITICAL'; }); sev = hasCrit ? 'CRITICAL' : 'WARN'; msg = 'Sesja Managed Agents zakonczona z ostrzezeniami (' + warnings.length + ') [status: ' + (o.status || '?') + '] dla zadania ' + (o.clickup_task_id || '?'); det = warnings.map(function(w){ return (w.source || '') + ': ' + (w.err || ''); }).join(' | ').slice(0,1500); }
return [{ json: Object.assign({}, o, { do_alert: do_alert, _sev: sev, _msg: msg, _details: det }) }];

// SOLE non-recursive TERMINAL. Re-reads the canonical output object from Merge Final (NOT its direct
// input, which Post Alert would have replaced) — the research-the-web return-determinism idiom — and folds
// in cost_pln = THIS session's own PLN cost from Log Session Cost (Log Model Run's cost_pln_total). The
// orchestrator's managed-lane comment footer uses cost_pln so it shows the PER-EXECUTION cost, NOT the
// task's cumulative total (the cumulative figure is what Write Cost Field writes to the CU 'Koszt akcji'
// field). Image-gen cost is logged separately per-image (Generate Images Parallel) and is intentionally
// NOT folded in here. Log Session Cost only runs on the normal terminal (Build Final Output) path; on the
// create/send-failed paths it never runs, so cost_pln falls back to null.
const out = $('Merge Final').first().json;
let cost_pln = null;
try { const c = $('Log Session Cost').first().json; if (c && c.cost_pln_total != null && !isNaN(Number(c.cost_pln_total))) cost_pln = Number(c.cost_pln_total); } catch (e) {}
return [{ json: Object.assign({}, out, { cost_pln: cost_pln }) }];
